__global__ void copy_factor_and_convert_panel_kernel(
        const float* __restrict__ factor,
        float* __restrict__ output,
        int leading_output,
        const float* __restrict__ source,
        __half* __restrict__ compact,
        int rows,
        int leading) {
    constexpr int tile_size = 32;
    constexpr int tiles = 4096 / tile_size;
    constexpr int lower_tile_tasks = tiles * (tiles + 1) / 2;
    constexpr int cluster_tiles = 256 / tile_size;
    constexpr int upper_tiles_per_cluster =
        cluster_tiles * (cluster_tiles - 1) / 2;
    constexpr int diagonal_clusters = 4096 / 256;
    constexpr int clear_tile_tasks =
        diagonal_clusters * upper_tiles_per_cluster;
    constexpr int factor_tasks = lower_tile_tasks + clear_tile_tasks;
    __shared__ float tile[tile_size][tile_size + 1];
    __shared__ int mapped_row;
    __shared__ int mapped_col;

    const int task = static_cast<int>(blockIdx.x);
    if (task < lower_tile_tasks) {
        if (threadIdx.x == 0) {
            int tile_row = static_cast<int>(
                (sqrtf(8.0f * static_cast<float>(task) + 1.0f) - 1.0f)
                * 0.5f);
            int base = tile_row * (tile_row + 1) / 2;
            if (base > task) {
                --tile_row;
                base = tile_row * (tile_row + 1) / 2;
            } else if (base + tile_row + 1 <= task) {
                ++tile_row;
                base = tile_row * (tile_row + 1) / 2;
            }
            mapped_row = tile_row;
            mapped_col = task - base;
        }
        __syncthreads();
        const int tx = threadIdx.x & (tile_size - 1);
        const int ty = threadIdx.x >> 5;
        const int row_base = mapped_row * tile_size;
        const int col_base = mapped_col * tile_size;
        for (int y = ty; y < tile_size; y += 8) {
            tile[y][tx] = factor[
                row_base + tx + static_cast<int64_t>(col_base + y) * 4096
            ];
        }
        __syncthreads();
        for (int y = ty; y < tile_size; y += 8) {
            const int row = row_base + y;
            const int col = col_base + tx;
            output[static_cast<int64_t>(row) * leading_output + col] =
                row >= col ? tile[tx][y] : 0.0f;
        }
        return;
    }

    if (task < factor_tasks) {
        if (threadIdx.x == 0) {
            const int upper_task = task - lower_tile_tasks;
            const int cluster = upper_task / upper_tiles_per_cluster;
            int within = upper_task - cluster * upper_tiles_per_cluster;
            int tile_col = 1;
            while (within >= tile_col) {
                within -= tile_col;
                ++tile_col;
            }
            mapped_row = cluster * cluster_tiles + within;
            mapped_col = cluster * cluster_tiles + tile_col;
        }
        __syncthreads();
        const int tx = threadIdx.x & (tile_size - 1);
        const int ty = threadIdx.x >> 5;
        const int row_base = mapped_row * tile_size;
        const int col_base = mapped_col * tile_size;
        for (int y = ty; y < tile_size; y += 8) {
            output[
                static_cast<int64_t>(row_base + y) * leading_output
                + col_base + tx
            ] = 0.0f;
        }
        return;
    }

    constexpr int groups_per_row = 512;
    const int converter_blocks = static_cast<int>(gridDim.x) - factor_tasks;
    const int converter_block = task - factor_tasks;
    const int64_t total = static_cast<int64_t>(rows) * groups_per_row;
    for (int64_t index =
             static_cast<int64_t>(converter_block) * blockDim.x + threadIdx.x;
         index < total;
         index += static_cast<int64_t>(converter_blocks) * blockDim.x) {
        const int row = static_cast<int>(index >> 9);
        const int group = static_cast<int>(index & (groups_per_row - 1));
        const float4* source_vectors = reinterpret_cast<const float4*>(
            source + static_cast<int64_t>(row) * leading);
        const float4 first = source_vectors[group * 2];
        const float4 second = source_vectors[group * 2 + 1];
        __half2* destination = reinterpret_cast<__half2*>(
            compact + static_cast<int64_t>(row) * 4096);
        destination[group * 4] = __floats2half2_rn(first.x, first.y);
        destination[group * 4 + 1] = __floats2half2_rn(first.z, first.w);
        destination[group * 4 + 2] = __floats2half2_rn(second.x, second.y);
        destination[group * 4 + 3] = __floats2half2_rn(second.z, second.w);
    }
}

void copy_factor_and_convert_panel_(
        torch::Tensor factor,
        torch::Tensor output,
        torch::Tensor panel,
        torch::Tensor compact) {
    TORCH_CHECK(
        factor.is_cuda() && output.is_cuda() && panel.is_cuda()
        && compact.is_cuda(),
        "CUDA tensors required");
    TORCH_CHECK(
        factor.scalar_type() == at::kFloat
        && output.scalar_type() == at::kFloat
        && panel.scalar_type() == at::kFloat
        && compact.scalar_type() == at::kHalf,
        "compatible FP32/FP16 tensors required");
    TORCH_CHECK(
        factor.dim() == 3 && output.dim() == 3
        && factor.sizes() == output.sizes()
        && factor.size(0) == 1 && factor.size(1) == 4096
        && factor.stride(1) == 1 && factor.stride(2) == 4096
        && output.stride(2) == 1,
        "compatible 4096-square factors required");
    TORCH_CHECK(
        panel.dim() == 2 && compact.dim() == 2
        && panel.size(0) == compact.size(0)
        && panel.size(1) == 4096 && compact.size(1) == 4096
        && panel.stride(1) == 1 && compact.is_contiguous(),
        "compatible 4096-column panels required");
    constexpr int tiles = 4096 / 32;
    constexpr int lower_tile_tasks = tiles * (tiles + 1) / 2;
    constexpr int clear_tile_tasks = (4096 / 256) * (8 * 7 / 2);
    constexpr int factor_tasks = lower_tile_tasks + clear_tile_tasks;
    const int64_t groups = panel.size(0) * 512;
    const int conversion_blocks = static_cast<int>(
        std::min<int64_t>((groups + 255) / 256, 4096));
    copy_factor_and_convert_panel_kernel<<<
        factor_tasks + conversion_blocks, 256, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()>>>(
            factor.data_ptr<float>(), output.data_ptr<float>(),
            static_cast<int>(output.stride(1)), panel.data_ptr<float>(),
            reinterpret_cast<__half*>(compact.data_ptr<at::Half>()),
            static_cast<int>(panel.size(0)),
            static_cast<int>(panel.stride(0)));
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void grouped_pointer_table_kernel(
        float* output,
        int64_t* pointers,
        int batch,
        int n,
        int block,
        int panels) {
    const int index = static_cast<int>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int count = panels * 2 * batch;
    if (index >= count) {
        return;
    }
    const int matrix = index % batch;
    const int table = index / batch;
    const int kind = table & 1;
    const int panel = table >> 1;
    const int start = panel * block;
    const int stop = min(start + block, n);
    const int64_t matrix_base = static_cast<int64_t>(matrix) * n * n;
    const int64_t element = kind == 0
        ? matrix_base + static_cast<int64_t>(start) * (n + 1)
        : matrix_base + static_cast<int64_t>(start) * n + stop;
    pointers[index] = reinterpret_cast<int64_t>(output + element);

